-- Keep identity sequences ahead of seeded primary keys (create-drop + explicit IDs).
SELECT setval(pg_get_serial_sequence('loyalty_program', 'id'), COALESCE((SELECT MAX(id) FROM loyalty_program), 1));
SELECT setval(pg_get_serial_sequence('penal', 'id'), COALESCE((SELECT MAX(id) FROM penal), 1));

-- Seed customer mail@mail.com (id=1) must have a penalty row for reservation flows.
SELECT COALESCE((SELECT MAX(id) FROM penal), 0) + 1, 1, 0
WHERE NOT EXISTS (SELECT 1 FROM public.penal WHERE customer = 1);

